-- NIKRION Governance & Authority Engine v1
ALTER TABLE users ADD COLUMN IF NOT EXISTS authority_level VARCHAR(40), ADD COLUMN IF NOT EXISTS can_approve_lead_edit BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS can_direct_edit_lead BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS can_modify_vehicle_master BOOLEAN DEFAULT false, ADD COLUMN IF NOT EXISTS can_modify_organization BOOLEAN DEFAULT false;
CREATE TABLE IF NOT EXISTS lead_edit_requests (id SERIAL PRIMARY KEY, lead_id INTEGER REFERENCES leads(id) ON DELETE CASCADE, requested_by INTEGER REFERENCES users(id), approved_by INTEGER REFERENCES users(id), request_status VARCHAR(40) DEFAULT 'PENDING', requested_changes JSONB DEFAULT '{}'::jsonb, reason TEXT, manager_remarks TEXT, requested_at TIMESTAMP DEFAULT NOW(), reviewed_at TIMESTAMP, created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_lead_edit_requests_lead ON lead_edit_requests(lead_id);
CREATE INDEX IF NOT EXISTS idx_lead_edit_requests_status ON lead_edit_requests(request_status);
CREATE INDEX IF NOT EXISTS idx_lead_edit_requests_requested_by ON lead_edit_requests(requested_by);
INSERT INTO permission_master (permission_key, permission_label, module_name) VALUES ('lead_edit.request','Request Lead Edit Approval','Governance'),('lead_edit.approve','Approve Lead Edit Requests','Governance'),('lead.edit.direct','Direct Critical Lead Edit','Governance'),('vehicle.status.view','View Vehicle Status Only','Governance'),('vehicle.dashboard.view','View Vehicle Dashboard','Governance'),('vehicle.modify','Modify Vehicle Master','Governance'),('organization.modify','Modify Organization / Department / Branch','Governance'),('reports.generate','Generate Reports','Governance'),('reports.auto_generate','Auto Generate Reports','Governance') ON CONFLICT (permission_key) DO NOTHING;
